import { type ButtonHTMLAttributes, type FormEvent, type HTMLAttributes, type InputHTMLAttributes, type ReactNode, type SelectHTMLAttributes, useMemo, useState } from 'react';
import { QueryClient, QueryClientProvider, useQueryClient } from '@tanstack/react-query';
import { Link, Route, Switch, Router as WouterRouter, useLocation } from 'wouter';
import {
  Activity as ActivityIcon, ArrowUpRight, BarChart3, Bell, CalendarDays,
  Check, CheckCircle2, ChevronLeft, ChevronRight, CircleDollarSign,
  FileText, FlaskConical, LayoutDashboard, Menu, MoreHorizontal, Phone,
  Plus, ReceiptText, RefreshCw, Search, Settings, SlidersHorizontal, Stethoscope,
  UserRound, UsersRound, WalletCards, X, XCircle, Zap
} from 'lucide-react';
import {
  getGetDashboardSummaryQueryKey, getListAppointmentsQueryKey, getListPatientsQueryKey,
  useCreateAppointment, useCreatePatient, useGetAppointment, useGetDashboardSummary,
  useListActivity, useListAppointments, useListPatients, useListSlots, useListTests,
  useUpdateAppointmentPayment, useUpdateAppointmentStatus
} from '@workspace/api-client-react';
import type {
  Activity, Appointment, DashboardSummary, Patient, PatientInput, Slot, Test
} from '@workspace/api-client-react';
import { ErrorBoundary } from '@/components/error-boundary';
import NotFound from '@/pages/not-found';
import { Toaster } from '@/components/ui/toaster';
import { TooltipProvider } from '@/components/ui/tooltip';
import { toast } from 'sonner';

const queryClient = new QueryClient();
const today = new Date().toISOString().slice(0, 10);

const nav = [
  { href: '/', label: 'Overview', icon: LayoutDashboard },
  { href: '/appointments', label: 'Appointments', icon: CalendarDays },
  { href: '/patients', label: 'Patients', icon: UsersRound },
  { href: '/tests', label: 'Test catalogue', icon: FlaskConical },
  { href: '/reports', label: 'Reports', icon: FileText },
  { href: '/analytics', label: 'Analytics', icon: BarChart3 },
];

function cx(...classes: Array<string | false | null | undefined>) { return classes.filter(Boolean).join(' '); }
function money(value = 0) { return `₹${value.toLocaleString('en-IN')}`; }
function formatDay(value?: string) {
  if (!value) return '—';
  const date = new Date(`${value}T00:00:00`);
  return Number.isNaN(date.valueOf()) ? value : date.toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' });
}
function initials(name = '') { return name.split(' ').map((part) => part[0]).slice(0, 2).join('').toUpperCase() || 'PT'; }
function statusTone(status = '') {
  const normalized = status.toLowerCase();
  if (['confirmed', 'completed', 'paid', 'ready', 'available'].includes(normalized)) return 'bg-[#e5f5f1] text-[#167366]';
  if (['pending', 'partial', 'processing', 'reserved'].includes(normalized)) return 'bg-[#fff2dd] text-[#a96816]';
  if (['cancelled', 'failed', 'unpaid', 'blocked'].includes(normalized)) return 'bg-[#fce9e8] text-[#b34b48]';
  return 'bg-[#e9f0f5] text-[#536675]';
}
function titleCase(value = '') { return value.replace(/_/g, ' ').replace(/\b\w/g, (letter) => letter.toUpperCase()); }

function Panel({ children, className = '', ...props }: { children: ReactNode; className?: string } & HTMLAttributes<HTMLElement>) {
  return <section className={cx('rounded-2xl border border-border bg-card shadow-[0_5px_18px_hsl(210_20%_60%_/_0.06)]', className)} {...props}>{children}</section>;
}
function PageTitle({ eyebrow, title, detail, action }: { eyebrow: string; title: string; detail: string; action?: ReactNode }) {
  return <div className="mb-7 flex flex-col justify-between gap-4 md:flex-row md:items-end">
    <div><div className="mono mb-2 text-[10px] font-bold uppercase tracking-[0.2em] text-primary">{eyebrow}</div><h1 className="text-[28px] font-bold tracking-[-0.04em] text-foreground md:text-[34px]">{title}</h1><p className="mt-1 text-sm text-muted-foreground">{detail}</p></div>
    {action}
  </div>;
}
function Button({ children, variant = 'primary', className = '', ...props }: ButtonHTMLAttributes<HTMLButtonElement> & { variant?: 'primary' | 'secondary' | 'ghost' | 'danger' }) {
  return <button className={cx('inline-flex h-10 items-center justify-center gap-2 rounded-xl px-4 text-sm font-semibold transition-transform duration-200 active:scale-[.98] disabled:cursor-not-allowed disabled:opacity-50', variant === 'primary' && 'bg-primary text-primary-foreground hover:brightness-105', variant === 'secondary' && 'border border-border bg-card text-foreground hover:bg-muted', variant === 'ghost' && 'text-muted-foreground hover:bg-muted hover:text-foreground', variant === 'danger' && 'bg-destructive text-destructive-foreground hover:brightness-105', className)} {...props}>{children}</button>;
}
function Field({ label, children, className = '' }: { label: string; children: ReactNode; className?: string }) {
  return <label className={cx('block space-y-1.5', className)}><span className="text-xs font-semibold text-muted-foreground">{label}</span>{children}</label>;
}
function Input({ className = '', ...props }: InputHTMLAttributes<HTMLInputElement>) {
  return <input className={cx('h-10 w-full rounded-xl border border-input bg-background px-3 text-sm outline-none transition focus:border-primary focus:ring-2 focus:ring-primary/15', className)} {...props} />;
}
function Select({ className = '', ...props }: SelectHTMLAttributes<HTMLSelectElement>) {
  return <select className={cx('h-10 w-full rounded-xl border border-input bg-background px-3 text-sm outline-none transition focus:border-primary focus:ring-2 focus:ring-primary/15', className)} {...props} />;
}
function EmptyState({ icon: Icon, title, detail, action }: { icon: typeof Search; title: string; detail: string; action?: ReactNode }) {
  return <div className="flex min-h-[230px] flex-col items-center justify-center px-6 text-center"><div className="mb-3 rounded-2xl bg-muted p-3 text-primary"><Icon size={22} /></div><h3 className="font-semibold">{title}</h3><p className="mt-1 max-w-sm text-sm text-muted-foreground">{detail}</p>{action && <div className="mt-4">{action}</div>}</div>;
}
function QueryState({ loading, error, children, empty, retry }: { loading: boolean; error: boolean; children: ReactNode; empty?: boolean; retry?: () => void }) {
  if (loading) return <div className="space-y-3 p-5">{[1, 2, 3, 4].map((i) => <div key={i} className="skeleton h-14 rounded-xl" />)}</div>;
  if (error) return <div className="flex min-h-[220px] flex-col items-center justify-center gap-3 p-6 text-center"><XCircle className="text-destructive" size={28} /><h3 className="font-semibold">Could not load this view</h3><p className="text-sm text-muted-foreground">The workspace service did not respond. Try again.</p>{retry && <Button variant="secondary" onClick={retry}><RefreshCw size={15} /> Retry</Button>}</div>;
  if (empty) return <>{children}</>;
  return <>{children}</>;
}

function Shell({ children }: { children: ReactNode }) {
  const [location, setLocation] = useLocation();
  const [mobileNav, setMobileNav] = useState(false);
  const [profileMenu, setProfileMenu] = useState(false);
  const current = nav.find((item) => item.href === location)?.label || (location === '/settings' ? 'Settings' : 'Workspace');
  return <div className="min-h-[100dvh] bg-background text-foreground">
    <aside className={cx('fixed inset-y-0 left-0 z-40 flex w-[248px] flex-col bg-sidebar px-4 py-5 text-sidebar-foreground transition-transform duration-300 md:translate-x-0', mobileNav ? 'translate-x-0' : '-translate-x-full')}>
      <div className="flex items-center gap-3 px-3"><div className="grid size-9 place-items-center rounded-xl bg-sidebar-primary text-sidebar-primary-foreground"><Stethoscope size={19} /></div><div><div className="text-sm font-bold tracking-tight text-white">Nivara Diagnostics</div><div className="mono text-[9px] uppercase tracking-[.16em] text-sidebar-foreground/60">Ops console</div></div></div>
      <div className="mono mb-2 mt-10 px-3 text-[10px] font-bold uppercase tracking-[.18em] text-sidebar-foreground/45">Workspace</div>
      <nav className="space-y-1">{nav.map(({ href, label, icon: Icon }) => <Link key={href} href={href} data-testid={`link-nav-${label.toLowerCase().replaceAll(' ', '-')}`} onClick={() => setMobileNav(false)} className={cx('group flex h-10 items-center gap-3 rounded-xl px-3 text-sm font-medium transition-colors', location === href ? 'bg-sidebar-accent text-white' : 'text-sidebar-foreground/70 hover:bg-sidebar-accent/70 hover:text-white')}><Icon size={17} className={location === href ? 'text-sidebar-primary' : ''} /><span>{label}</span>{href === '/appointments' && <span className="mono ml-auto rounded-md bg-sidebar-primary/15 px-1.5 py-0.5 text-[9px] text-sidebar-primary">LIVE</span>}</Link>)}</nav>
      <div className="mono mb-2 mt-8 px-3 text-[10px] font-bold uppercase tracking-[.18em] text-sidebar-foreground/45">Workspace admin</div>
      <Link href="/settings" data-testid="link-nav-settings" onClick={() => setMobileNav(false)} className={cx('flex h-10 items-center gap-3 rounded-xl px-3 text-sm font-medium', location === '/settings' ? 'bg-sidebar-accent text-white' : 'text-sidebar-foreground/70 hover:bg-sidebar-accent/70 hover:text-white')}><Settings size={17} /><span>Settings</span></Link>
      <div className="relative mt-auto rounded-2xl border border-sidebar-border bg-sidebar-accent/60 p-3"><button type="button" aria-label="Open profile menu" data-testid="button-profile-menu" onClick={() => setProfileMenu((open) => !open)} className="flex w-full items-center gap-2 text-left"><div className="grid size-8 place-items-center rounded-full bg-[#d6eee9] text-xs font-bold text-[#176e64]">AK</div><div className="min-w-0"><div className="truncate text-xs font-semibold text-white">Aarav Kulkarni</div><div className="truncate text-[10px] text-sidebar-foreground/55">Frontdesk lead</div></div><MoreHorizontal size={15} className="ml-auto text-sidebar-foreground/50" /></button>{profileMenu && <div className="absolute bottom-[calc(100%+8px)] left-0 right-0 overflow-hidden rounded-xl border border-sidebar-border bg-[#173c4c] p-1.5 shadow-xl"><div className="px-2.5 py-2 text-[11px] text-sidebar-foreground/60">Signed in as Aarav</div><button type="button" data-testid="button-logout" onClick={() => { setProfileMenu(false); toast.success('You have been logged out'); }} className="w-full rounded-lg px-2.5 py-2 text-left text-xs font-semibold text-white hover:bg-sidebar-accent">Log out</button></div>}<div className="mt-3 flex items-center gap-1.5 text-[10px] text-sidebar-foreground/55"><span className="size-1.5 rounded-full bg-sidebar-primary" /> All systems operational</div></div>
    </aside>
    {mobileNav && <button aria-label="Close navigation" className="fixed inset-0 z-30 bg-foreground/25 md:hidden" onClick={() => setMobileNav(false)} />}
    <div className="md:pl-[248px]">
      <header className="sticky top-0 z-20 flex h-[72px] items-center justify-between border-b border-border/70 bg-background/90 px-5 backdrop-blur-md md:px-9"><div className="flex items-center gap-3"><Button variant="ghost" className="px-2 md:hidden" onClick={() => setMobileNav(true)}><Menu size={20} /></Button><div><div className="mono text-[10px] font-bold uppercase tracking-[.18em] text-muted-foreground">Nivara / {current}</div><div className="mt-0.5 text-sm font-semibold text-foreground">{location === '/' ? 'Good morning, Aarav' : current}</div></div></div><div className="flex items-center gap-2"><div className="hidden items-center gap-2 rounded-xl border border-border bg-card px-3 py-2 text-xs text-muted-foreground sm:flex"><span className="size-2 rounded-full bg-[#38a88e]" /> Mumbai · Andheri West</div><button aria-label="Notifications" data-testid="button-notifications" className="relative grid size-10 place-items-center rounded-xl border border-border bg-card text-muted-foreground hover:bg-muted"><Bell size={17} /><span className="absolute right-2 top-2 size-1.5 rounded-full bg-accent" /></button></div></header>
      <main className="page-enter mx-auto max-w-[1500px] px-5 py-7 md:px-9">{children}</main>
    </div>
  </div>;
}

function MetricCard({ label, value, detail, icon: Icon, tone = 'teal', trend }: { label: string; value: string | number; detail: string; icon: typeof CalendarDays; tone?: 'teal' | 'amber' | 'blue' | 'coral'; trend?: string }) {
  return <Panel className="rise-in relative overflow-hidden p-5"><div className={cx('absolute right-0 top-0 h-20 w-20 rounded-bl-[50px] opacity-70', tone === 'teal' && 'bg-[#e5f5f1]', tone === 'amber' && 'bg-[#fff2dd]', tone === 'blue' && 'bg-[#e8f0f8]', tone === 'coral' && 'bg-[#fce9e8]')} /><div className="relative flex items-start justify-between"><div><div className="text-xs font-semibold text-muted-foreground">{label}</div><div className="mt-2 text-[29px] font-bold tracking-[-.06em]">{value}</div><div className="mt-1 text-xs text-muted-foreground">{detail}</div></div><div className={cx('grid size-9 place-items-center rounded-xl', tone === 'teal' && 'bg-[#e5f5f1] text-[#167366]', tone === 'amber' && 'bg-[#fff2dd] text-[#a96816]', tone === 'blue' && 'bg-[#e8f0f8] text-[#32607e]', tone === 'coral' && 'bg-[#fce9e8] text-[#b34b48]')}><Icon size={18} /></div></div>{trend && <div className="absolute bottom-4 right-5 flex items-center gap-1 text-[10px] font-semibold text-[#167366]"><ArrowUpRight size={12} />{trend}</div>}</Panel>;
}

function Dashboard() {
  const summaryQuery = useGetDashboardSummary();
  const activityQuery = useListActivity();
  const appointmentQuery = useListAppointments({ page: 1, pageSize: 6, date: today });
  const summary = summaryQuery.data as DashboardSummary | undefined;
  const appointments = appointmentQuery.data?.items ?? [];
  const activities = (activityQuery.data as Activity[] | undefined) ?? [];
  const trend = summary?.appointmentTrend ?? [];
  const maxTrend = Math.max(...trend.map((item) => item.value), 1);
  const breakdown = summary?.statusBreakdown ?? [];
  return <><PageTitle eyebrow="Tuesday · 18 June 2024" title="Today's control room" detail="A clear view of patient movement, cash position, and work still in flight." action={<Link href="/new-appointment" data-testid="link-new-appointment-dashboard"><Button><Plus size={16} /> New appointment</Button></Link>} />
    <QueryState loading={summaryQuery.isLoading} error={!!summaryQuery.error} retry={() => summaryQuery.refetch()}><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
      <MetricCard label="Appointments today" value={summary?.todayAppointments ?? '—'} detail={`${summary?.confirmed ?? 0} confirmed · ${summary?.pending ?? 0} pending`} icon={CalendarDays} tone="teal" trend="+8.4% vs last Tue" />
      <MetricCard label="Collected today" value={summary ? money(summary.revenue) : '—'} detail={`${summary?.pendingPayments ?? 0} payments to reconcile`} icon={CircleDollarSign} tone="amber" />
      <MetricCard label="Completed" value={summary?.completed ?? '—'} detail="Patients checked through" icon={CheckCircle2} tone="blue" trend="On track" />
      <MetricCard label="Reports pending" value={summary?.reportsPending ?? '—'} detail={`${summary?.whatsappSent ?? 0} updates sent on WhatsApp`} icon={FileText} tone="coral" />
    </div></QueryState>
    <div className="mt-5 grid gap-5 xl:grid-cols-[1.5fr_1fr]">
      <Panel className="p-5"><div className="mb-5 flex items-start justify-between"><div><h2 className="font-semibold">Appointment volume</h2><p className="mt-1 text-xs text-muted-foreground">Booked visits across the last seven days</p></div><div className="rounded-lg bg-[#e5f5f1] px-2.5 py-1 text-xs font-semibold text-[#167366]">This week</div></div><div className="flex h-[188px] items-end gap-2 sm:gap-4">{trend.length ? trend.map((item, index) => <div key={item.label} className="flex h-full flex-1 flex-col items-center justify-end gap-2"><div className="relative flex w-full max-w-10 flex-1 items-end rounded-t-lg bg-muted"><div className={cx('w-full rounded-t-lg transition-all', index === trend.length - 1 ? 'bg-primary' : 'bg-[#9ccfc6]')} style={{ height: `${Math.max(10, (item.value / maxTrend) * 100)}%` }}><span className="absolute -mt-5 w-full text-center text-[10px] font-bold text-muted-foreground">{item.value}</span></div></div><span className="text-[10px] font-medium text-muted-foreground">{item.label}</span></div>) : <div className="flex w-full items-center justify-center text-sm text-muted-foreground">No appointment trend yet</div>}</div></Panel>
      <Panel className="p-5"><div className="mb-5"><h2 className="font-semibold">Status mix</h2><p className="mt-1 text-xs text-muted-foreground">Where today's appointments stand</p></div><div className="space-y-4">{breakdown.length ? breakdown.map((item, index) => <div key={item.label}><div className="mb-1.5 flex justify-between text-xs"><span className="font-medium">{titleCase(item.label)}</span><span className="mono text-muted-foreground">{item.value}</span></div><div className="h-2 overflow-hidden rounded-full bg-muted"><div className={cx('h-full rounded-full', ['bg-primary', 'bg-[#e8a84d]', 'bg-[#7397b2]', 'bg-[#d47770]'][index % 4])} style={{ width: `${summary?.todayAppointments ? (item.value / summary.todayAppointments) * 100 : 0}%` }} /></div></div>) : <div className="py-8 text-center text-sm text-muted-foreground">No status data yet</div>}</div></Panel>
    </div>
    <div className="mt-5 grid gap-5 xl:grid-cols-[1.45fr_1fr]">
      <Panel><div className="flex items-center justify-between border-b border-border px-5 py-4"><div><h2 className="font-semibold">Today's appointment board</h2><p className="mt-1 text-xs text-muted-foreground">The next patients through the frontdesk</p></div><Link href="/appointments" data-testid="link-view-all-appointments" className="text-xs font-bold text-primary hover:underline">View all</Link></div><QueryState loading={appointmentQuery.isLoading} error={!!appointmentQuery.error} retry={() => appointmentQuery.refetch()}>{appointments.length ? <div className="divide-y divide-border">{appointments.map((appointment) => <AppointmentRow key={appointment.id} appointment={appointment} compact />)}</div> : <EmptyState icon={CalendarDays} title="No appointments on the board" detail="The day's schedule will appear here as soon as bookings are made." action={<Link href="/new-appointment" data-testid="link-empty-new-appointment"><Button><Plus size={15} /> Add booking</Button></Link>} />}</QueryState></Panel>
      <Panel><div className="border-b border-border px-5 py-4"><h2 className="font-semibold">Recent activity</h2><p className="mt-1 text-xs text-muted-foreground">Live updates from across the workspace</p></div><QueryState loading={activityQuery.isLoading} error={!!activityQuery.error} retry={() => activityQuery.refetch()}>{activities.length ? <div className="divide-y divide-border">{activities.slice(0, 6).map((activity) => <ActivityRow key={activity.id} activity={activity} />)}</div> : <EmptyState icon={ActivityIcon} title="No activity yet" detail="Operational events will be recorded here." />}</QueryState></Panel>
    </div>
    <Panel className="mt-5 border-[#b9ddd6] bg-[#edf8f5] p-5"><div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between"><div className="flex items-center gap-3"><div className="grid size-10 place-items-center rounded-xl bg-primary text-primary-foreground"><Zap size={18} /></div><div><div className="font-semibold text-[#175b54]">Keep the queue moving</div><p className="mt-1 text-xs text-[#4d766f]">Fast actions for the moments that matter at frontdesk.</p></div></div><div className="flex flex-wrap gap-2"><Link href="/new-appointment" data-testid="link-quick-book"><Button variant="secondary" className="border-[#b9ddd6] bg-card"><Plus size={14} /> Book patient</Button></Link><Link href="/patients" data-testid="link-quick-patient"><Button variant="secondary" className="border-[#b9ddd6] bg-card"><UserRound size={14} /> Find patient</Button></Link><Link href="/reports" data-testid="link-quick-reports"><Button variant="secondary" className="border-[#b9ddd6] bg-card"><FileText size={14} /> Report queue</Button></Link></div></div></Panel>
  </>;
}

function ActivityRow({ activity }: { activity: Activity }) {
  const Icon = activity.type === 'payment' ? CircleDollarSign : activity.type === 'report' ? FileText : activity.type === 'appointment' ? CalendarDays : ActivityIcon;
  return <div className="flex gap-3 px-5 py-3.5"><div className="mt-0.5 grid size-8 shrink-0 place-items-center rounded-lg bg-muted text-primary"><Icon size={15} /></div><div className="min-w-0 flex-1"><div className="truncate text-xs font-semibold">{activity.title}</div><div className="mt-0.5 truncate text-[11px] text-muted-foreground">{activity.detail}</div></div><span className="mono shrink-0 text-[10px] text-muted-foreground">{activity.time}</span></div>;
}

function AppointmentRow({ appointment, compact = false, onChange }: { appointment: Appointment; compact?: boolean; onChange?: () => void }) {
  const queryClient = useQueryClient();
  const detailQuery = useGetAppointment(appointment.id);
  const statusMutation = useUpdateAppointmentStatus();
  const paymentMutation = useUpdateAppointmentPayment();
  const updateStatus = (status: string) => statusMutation.mutate({ id: appointment.id, data: { status } }, { onSuccess: () => { toast.success(`Appointment marked ${titleCase(status)}`); queryClient.invalidateQueries({ queryKey: getListAppointmentsQueryKey() }); queryClient.invalidateQueries({ queryKey: getGetDashboardSummaryQueryKey() }); onChange?.(); }, onError: () => toast.error('Could not update appointment status') });
  const updatePayment = (paymentStatus: string) => paymentMutation.mutate({ id: appointment.id, data: { paymentStatus } }, { onSuccess: () => { toast.success('Payment status updated'); queryClient.invalidateQueries({ queryKey: getListAppointmentsQueryKey() }); queryClient.invalidateQueries({ queryKey: getGetDashboardSummaryQueryKey() }); onChange?.(); }, onError: () => toast.error('Could not update payment status') });
  return <div className={cx('flex items-center gap-3 px-5 py-3.5 transition-colors hover:bg-muted/40', !compact && 'min-w-[980px]')}><div className="grid size-9 shrink-0 place-items-center rounded-full bg-[#dcefeb] text-xs font-bold text-[#187367]">{initials(appointment.patientName)}</div><div className="min-w-[140px] flex-1"><div className="text-sm font-semibold">{appointment.patientName}</div><div className="mono mt-0.5 text-[10px] text-muted-foreground">{appointment.uhid} · {appointment.mobile}</div></div><div className="w-[150px] shrink-0"><div className="text-xs font-medium">{appointment.testName}</div><div className="mt-0.5 text-[10px] text-muted-foreground">{appointment.lab || appointment.branch}</div></div><div className="w-[90px] shrink-0"><div className="mono text-xs font-bold">{appointment.time}</div><div className="text-[10px] text-muted-foreground">{compact ? '' : formatDay(appointment.date)}</div></div><span className={cx('shrink-0 rounded-lg px-2 py-1 text-[10px] font-bold', statusTone(appointment.status))}>{titleCase(appointment.status)}</span>{!compact && <><button data-testid={`button-status-${appointment.id}`} title="Mark appointment completed" onClick={() => updateStatus(appointment.status === 'completed' ? 'confirmed' : 'completed')} disabled={statusMutation.isPending} className="grid size-8 shrink-0 place-items-center rounded-lg border border-border text-muted-foreground hover:bg-muted hover:text-primary"><Check size={15} /></button><button data-testid={`button-payment-${appointment.id}`} title="Toggle payment status" onClick={() => updatePayment(appointment.paymentStatus === 'paid' ? 'pending' : 'paid')} disabled={paymentMutation.isPending} className={cx('grid size-8 shrink-0 place-items-center rounded-lg border text-muted-foreground hover:bg-muted', appointment.paymentStatus === 'paid' ? 'border-[#b9ddd6] text-[#167366]' : 'border-border')}><WalletCards size={15} /></button></>}{compact && <span className={cx('shrink-0 rounded-lg px-2 py-1 text-[10px] font-bold', statusTone(appointment.paymentStatus))}>{titleCase(appointment.paymentStatus)}</span>}</div>;
}

function Appointments() {
  const [search, setSearch] = useState('');
  const [status, setStatus] = useState('all');
  const [date, setDate] = useState(today);
  const [page, setPage] = useState(1);
  const queryClient = useQueryClient();
  const mobileStatusMutation = useUpdateAppointmentStatus();
  const mobilePaymentMutation = useUpdateAppointmentPayment();
  const params = useMemo(() => ({ page, pageSize: 10, search: search || undefined, status: status === 'all' ? undefined : status, date: date || undefined }), [page, search, status, date]);
  const query = useListAppointments(params);
  const totalPages = Math.max(1, Math.ceil((query.data?.total ?? 0) / (query.data?.pageSize ?? 10)));
  const mobileStatus = (appointment: Appointment) => mobileStatusMutation.mutate({ id: appointment.id, data: { status: appointment.status === 'completed' ? 'confirmed' : 'completed' } }, { onSuccess: () => { toast.success('Appointment status updated'); queryClient.invalidateQueries({ queryKey: getListAppointmentsQueryKey() }); queryClient.invalidateQueries({ queryKey: getGetDashboardSummaryQueryKey() }); }, onError: () => toast.error('Could not update appointment status') });
  const mobilePayment = (appointment: Appointment) => mobilePaymentMutation.mutate({ id: appointment.id, data: { paymentStatus: appointment.paymentStatus === 'paid' ? 'pending' : 'paid' } }, { onSuccess: () => { toast.success('Payment status updated'); queryClient.invalidateQueries({ queryKey: getListAppointmentsQueryKey() }); queryClient.invalidateQueries({ queryKey: getGetDashboardSummaryQueryKey() }); }, onError: () => toast.error('Could not update payment status') });
  return <><PageTitle eyebrow="Operations / Queue" title="Appointments" detail="Search the queue, resolve exceptions, and keep every booking moving." action={<Link href="/new-appointment" data-testid="link-new-appointment"><Button><Plus size={16} /> New appointment</Button></Link>} />
    <Panel><div className="flex flex-col gap-3 border-b border-border p-4 lg:flex-row"><div className="relative flex-1"><Search className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" size={16} /><Input aria-label="Search appointments" data-testid="input-search-appointments" value={search} onChange={(event) => { setSearch(event.target.value); setPage(1); }} placeholder="Search patient, UHID, mobile, or test..." className="pl-9" /></div><div className="flex gap-2"><Select aria-label="Filter by status" data-testid="select-filter-status" value={status} onChange={(event) => { setStatus(event.target.value); setPage(1); }} className="w-[145px]"><option value="all">All statuses</option><option value="pending">Pending</option><option value="confirmed">Confirmed</option><option value="completed">Completed</option><option value="cancelled">Cancelled</option></Select><Input aria-label="Filter by date" data-testid="input-filter-date" type="date" value={date} onChange={(event) => { setDate(event.target.value); setPage(1); }} className="w-[145px]" /><Button variant="secondary" aria-label="More filters" data-testid="button-more-filters" className="px-3"><SlidersHorizontal size={16} /></Button></div></div><div className="hidden overflow-x-auto lg:block"><div className="flex min-w-[980px] items-center gap-3 border-b border-border bg-muted/45 px-5 py-3 text-[10px] font-bold uppercase tracking-[.12em] text-muted-foreground"><span className="w-9" /><span className="min-w-[140px] flex-1">Patient</span><span className="w-[150px]">Investigation</span><span className="w-[90px]">Slot</span><span className="w-[94px]">Status</span><span className="w-[74px]">Actions</span></div><QueryState loading={query.isLoading} error={!!query.error} retry={() => query.refetch()}>{query.data?.items.length ? query.data.items.map((appointment) => <AppointmentRow appointment={appointment} key={appointment.id} />) : <EmptyState icon={CalendarDays} title="No appointments match" detail="Try a wider date range or clear the current search and status filters." />}</QueryState></div><div className="lg:hidden"><QueryState loading={query.isLoading} error={!!query.error} retry={() => query.refetch()}>{query.data?.items.length ? query.data.items.map((appointment) => <div key={appointment.id} className="border-b border-border p-4"><div className="flex items-start gap-3"><div className="grid size-9 shrink-0 place-items-center rounded-full bg-[#dcefeb] text-xs font-bold text-[#187367]">{initials(appointment.patientName)}</div><div className="min-w-0 flex-1"><div className="font-semibold">{appointment.patientName}</div><div className="mono mt-0.5 text-[10px] text-muted-foreground">{appointment.uhid}</div><div className="mt-2 text-xs">{appointment.testName} · {appointment.time}</div></div><span className={cx('rounded-lg px-2 py-1 text-[10px] font-bold', statusTone(appointment.status))}>{titleCase(appointment.status)}</span></div><div className="mt-3 flex gap-2"><Button variant="secondary" className="h-8 flex-1 text-xs" onClick={() => {}} data-testid={`button-mobile-status-${appointment.id}`}><Check size={13} /> Complete</Button><Button variant="secondary" className="h-8 flex-1 text-xs" onClick={() => {}} data-testid={`button-mobile-payment-${appointment.id}`}><WalletCards size={13} /> Payment</Button></div></div>) : <EmptyState icon={CalendarDays} title="No appointments match" detail="Try a wider date range." />}</QueryState></div><div className="flex items-center justify-between border-t border-border px-5 py-3"><span className="text-xs text-muted-foreground">{query.data?.total ?? 0} appointments · page {page} of {totalPages}</span><div className="flex gap-1"><Button variant="ghost" className="size-8 px-0" disabled={page <= 1} onClick={() => setPage((current) => current - 1)} data-testid="button-previous-page"><ChevronLeft size={16} /></Button><Button variant="ghost" className="size-8 px-0" disabled={page >= totalPages} onClick={() => setPage((current) => current + 1)} data-testid="button-next-page"><ChevronRight size={16} /></Button></div></div></Panel>
  </>;
}

function Patients() {
  const [search, setSearch] = useState('');
  const [showCreate, setShowCreate] = useState(false);
  const query = useListPatients({ search: search || undefined });
  return <><PageTitle eyebrow="Directory / Master data" title="Patients" detail="A living master list for quick, confident frontdesk conversations." action={<Button onClick={() => setShowCreate(true)} data-testid="button-open-create-patient"><Plus size={16} /> Add patient</Button>} />
    <Panel><div className="flex flex-col gap-3 border-b border-border p-4 sm:flex-row"><div className="relative flex-1"><Search className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" size={16} /><Input aria-label="Search patients" data-testid="input-search-patients" value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search by name, UHID, mobile..." className="pl-9" /></div><div className="flex items-center gap-2 rounded-xl bg-muted px-3 text-xs text-muted-foreground"><UsersRound size={15} /> {query.data?.length ?? 0} visible records</div></div><QueryState loading={query.isLoading} error={!!query.error} retry={() => query.refetch()}>{query.data?.length ? <div className="overflow-x-auto"><table className="w-full min-w-[780px] text-left"><thead className="bg-muted/45 text-[10px] uppercase tracking-[.12em] text-muted-foreground"><tr><th className="px-5 py-3 font-bold">Patient</th><th className="px-4 py-3 font-bold">Contact</th><th className="px-4 py-3 font-bold">Profile</th><th className="px-4 py-3 font-bold">Last visit</th><th className="px-4 py-3 font-bold">Visits</th><th className="px-5 py-3" /></tr></thead><tbody className="divide-y divide-border">{query.data.map((patient) => <PatientRow key={patient.id} patient={patient} />)}</tbody></table></div> : <EmptyState icon={UsersRound} title={search ? 'No patient found' : 'Patient master is ready'} detail={search ? 'Try searching with a different name, mobile number, or UHID.' : 'Add your first patient to make booking flow faster.'} action={!search && <Button onClick={() => setShowCreate(true)} data-testid="button-empty-create-patient"><Plus size={15} /> Add patient</Button>} />}</QueryState></Panel>{showCreate && <PatientDialog onClose={() => setShowCreate(false)} />}</>;
}
function PatientRow({ patient }: { patient: Patient }) {
  return <tr className="transition-colors hover:bg-muted/35" data-testid={`row-patient-${patient.id}`}><td className="px-5 py-4"><div className="flex items-center gap-3"><div className="grid size-9 place-items-center rounded-full bg-[#dcefeb] text-xs font-bold text-[#187367]">{initials(patient.name)}</div><div><div className="text-sm font-semibold">{patient.name}</div><div className="mono mt-0.5 text-[10px] text-muted-foreground">{patient.uhid}</div></div></div></td><td className="px-4 py-4"><div className="text-xs">{patient.mobile}</div><div className="mt-0.5 text-[11px] text-muted-foreground">{patient.email || 'No email added'}</div></td><td className="px-4 py-4"><div className="text-xs">{patient.age} yrs · {titleCase(patient.gender)}</div><div className="mt-1 text-[10px] text-muted-foreground">{patient.whatsapp ? 'WhatsApp enabled' : 'WhatsApp not added'}</div></td><td className="px-4 py-4 text-xs text-muted-foreground">{formatDay(patient.lastVisit)}</td><td className="px-4 py-4"><span className="mono text-xs font-bold">{patient.totalVisits}</span></td><td className="px-5 py-4 text-right"><button aria-label={`Call ${patient.name}`} data-testid={`button-call-patient-${patient.id}`} className="grid size-8 place-items-center rounded-lg text-muted-foreground hover:bg-muted hover:text-primary"><Phone size={15} /></button></td></tr>;
}

function PatientDialog({ onClose }: { onClose: () => void }) {
  const [form, setForm] = useState<PatientInput>({ name: '', mobile: '', whatsapp: '', email: '', age: 0, gender: 'female' });
  const mutation = useCreatePatient();
  const queryClient = useQueryClient();
  const set = (key: keyof PatientInput, value: string | number) => setForm((current) => ({ ...current, [key]: value }));
  const submit = (event: FormEvent) => { event.preventDefault(); if (!form.name.trim() || form.mobile.length < 8 || form.age < 0) { toast.error('Add a name, valid mobile number, and age'); return; } mutation.mutate({ data: form }, { onSuccess: () => { queryClient.invalidateQueries({ queryKey: getListPatientsQueryKey() }); toast.success('Patient added to the master'); onClose(); }, onError: () => toast.error('Could not create patient') }); };
  return <div className="fixed inset-0 z-50 flex items-end justify-center bg-foreground/30 p-0 backdrop-blur-[2px] sm:items-center sm:p-5"><div className="w-full max-w-lg rounded-t-3xl border border-border bg-card shadow-2xl sm:rounded-3xl"><div className="flex items-center justify-between border-b border-border px-6 py-5"><div><div className="mono text-[10px] font-bold uppercase tracking-[.18em] text-primary">New record</div><h2 className="mt-1 text-xl font-bold">Add patient</h2></div><button aria-label="Close patient dialog" data-testid="button-close-patient-dialog" onClick={onClose} className="grid size-9 place-items-center rounded-xl text-muted-foreground hover:bg-muted"><X size={18} /></button></div><form onSubmit={submit} className="grid gap-4 p-6 sm:grid-cols-2"><Field label="Full name *" className="sm:col-span-2"><Input data-testid="input-patient-name" value={form.name} onChange={(event) => set('name', event.target.value)} placeholder="e.g. Meera Shah" /></Field><Field label="Mobile number *"><Input data-testid="input-patient-mobile" value={form.mobile} onChange={(event) => set('mobile', event.target.value)} placeholder="+91 98..." /></Field><Field label="WhatsApp number"><Input data-testid="input-patient-whatsapp" value={form.whatsapp} onChange={(event) => set('whatsapp', event.target.value)} placeholder="Same as mobile" /></Field><Field label="Age"><Input data-testid="input-patient-age" type="number" min="0" value={form.age} onChange={(event) => set('age', Number(event.target.value))} /></Field><Field label="Gender"><Select data-testid="select-patient-gender" value={form.gender} onChange={(event) => set('gender', event.target.value)}><option value="female">Female</option><option value="male">Male</option><option value="other">Other</option></Select></Field><Field label="Email address" className="sm:col-span-2"><Input data-testid="input-patient-email" type="email" value={form.email} onChange={(event) => set('email', event.target.value)} placeholder="Optional" /></Field><div className="mt-2 flex justify-end gap-2 sm:col-span-2"><Button type="button" variant="secondary" onClick={onClose} data-testid="button-cancel-patient">Cancel</Button><Button type="submit" disabled={mutation.isPending} data-testid="button-submit-patient">{mutation.isPending ? 'Saving...' : 'Create patient'}</Button></div></form></div></div>;
}

function NewAppointment() {
  const [form, setForm] = useState({ patientId: '', testId: '', date: today, time: '', slotId: '', source: 'frontdesk', paymentStatus: 'pending', doctor: '', notes: '' });
  const [patientSearch, setPatientSearch] = useState('');
  const [created, setCreated] = useState<Appointment | null>(null);
  const patientsQuery = useListPatients({ search: patientSearch || undefined });
  const testsQuery = useListTests();
  const slotsQuery = useListSlots({ date: form.date, testId: form.testId || undefined });
  const createMutation = useCreateAppointment();
  const queryClient = useQueryClient();
  const tests = testsQuery.data ?? [];
  const slots = (slotsQuery.data as Slot[] | undefined) ?? [];
  const selectedPatient = (patientsQuery.data as Patient[] | undefined)?.find((patient) => patient.id === form.patientId);
  const selectedTest = tests.find((test) => test.id === form.testId);
  const set = (key: string, value: string) => setForm((current) => ({ ...current, [key]: value, ...(key === 'date' ? { time: '', slotId: '' } : {}) }));
  const submit = (event: FormEvent) => { event.preventDefault(); if (!form.patientId || !form.testId || !form.slotId || !form.time) { toast.error('Select a patient, test, and available slot'); return; } createMutation.mutate({ data: form }, { onSuccess: (appointment) => { setCreated(appointment); queryClient.invalidateQueries({ queryKey: getListAppointmentsQueryKey() }); queryClient.invalidateQueries({ queryKey: getGetDashboardSummaryQueryKey() }); toast.success('Appointment booked'); }, onError: () => toast.error('Could not create appointment') }); };
  return <><PageTitle eyebrow="Operations / Booking" title="New appointment" detail="A focused booking flow designed for the frontdesk clock." action={<Link href="/appointments" data-testid="link-back-appointments"><Button variant="secondary"><ChevronLeft size={15} /> Back to queue</Button></Link>} />{created ? <Panel className="mx-auto max-w-2xl border-[#b9ddd6] bg-[#edf8f5] p-8 text-center"><div className="mx-auto grid size-14 place-items-center rounded-2xl bg-primary text-primary-foreground"><CheckCircle2 size={28} /></div><div className="mono mt-5 text-[10px] font-bold uppercase tracking-[.18em] text-primary">Booking confirmed</div><h2 className="mt-2 text-2xl font-bold">{created.patientName}</h2><p className="mt-2 text-sm text-muted-foreground">{created.testName} · {formatDay(created.date)} at {created.time}</p><div className="mt-6 flex justify-center gap-2"><Link href="/appointments" data-testid="link-created-view-appointments"><Button>View appointments</Button></Link><Button variant="secondary" onClick={() => { setCreated(null); setForm((current) => ({ ...current, patientId: '', time: '', slotId: '' })); }} data-testid="button-book-another">Book another</Button></div></Panel> : <form onSubmit={submit} className="grid gap-5 xl:grid-cols-[1fr_1fr_300px]"><Panel className="p-5"><div className="mb-5 flex items-center gap-3"><div className="grid size-9 place-items-center rounded-xl bg-[#e8f0f8] text-[#32607e]"><UserRound size={17} /></div><div><h2 className="font-semibold">Patient</h2><p className="text-xs text-muted-foreground">Find an existing record</p></div></div><Field label="Search patient"><div className="relative"><Search className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" size={15} /><Input data-testid="input-appointment-patient-search" value={patientSearch} onChange={(event) => { setPatientSearch(event.target.value); set('patientId', ''); }} placeholder="Name, UHID or mobile" className="pl-9" /></div></Field>{selectedPatient ? <div className="mt-4 flex items-center justify-between rounded-xl border border-[#b9ddd6] bg-[#edf8f5] p-3"><div className="flex items-center gap-2"><div className="grid size-8 place-items-center rounded-full bg-primary text-[10px] font-bold text-primary-foreground">{initials(selectedPatient.name)}</div><div><div className="text-sm font-semibold">{selectedPatient.name}</div><div className="mono text-[10px] text-muted-foreground">{selectedPatient.uhid}</div></div></div><button type="button" aria-label="Clear selected patient" data-testid="button-clear-selected-patient" onClick={() => set('patientId', '')} className="text-muted-foreground hover:text-foreground"><X size={15} /></button></div> : <div className="mt-3 max-h-[210px] overflow-y-auto scrollbar-thin">{patientSearch && patientsQuery.data?.slice(0, 6).map((patient) => <button type="button" key={patient.id} data-testid={`button-select-patient-${patient.id}`} onClick={() => { set('patientId', patient.id); setPatientSearch(patient.name); }} className="flex w-full items-center gap-3 rounded-xl px-2 py-2.5 text-left hover:bg-muted"><div className="grid size-8 place-items-center rounded-full bg-muted text-[10px] font-bold text-primary">{initials(patient.name)}</div><div><div className="text-xs font-semibold">{patient.name}</div><div className="mono text-[10px] text-muted-foreground">{patient.uhid} · {patient.mobile}</div></div></button>)}{patientSearch && !patientsQuery.isLoading && !patientsQuery.data?.length && <div className="p-3 text-xs text-muted-foreground">No matching patient. Add them from the Patients page first.</div>}</div>}<div className="mt-5 border-t border-border pt-5"><Field label="Source"><Select data-testid="select-appointment-source" value={form.source} onChange={(event) => set('source', event.target.value)}><option value="frontdesk">Frontdesk</option><option value="phone">Phone</option><option value="whatsapp">WhatsApp</option><option value="doctor_referral">Doctor referral</option></Select></Field></div></Panel>
      <Panel className="p-5"><div className="mb-5 flex items-center gap-3"><div className="grid size-9 place-items-center rounded-xl bg-[#fff2dd] text-[#a96816]"><FlaskConical size={17} /></div><div><h2 className="font-semibold">Investigation</h2><p className="text-xs text-muted-foreground">Choose test and visit time</p></div></div><Field label="Diagnostic test"><Select data-testid="select-appointment-test" value={form.testId} onChange={(event) => set('testId', event.target.value)}><option value="">Select a test</option>{tests.map((test) => <option key={test.id} value={test.id}>{test.name} · {money(test.price)}</option>)}</Select></Field><div className="mt-4 grid gap-3 sm:grid-cols-2"><Field label="Date"><Input data-testid="input-appointment-date" type="date" value={form.date} onChange={(event) => set('date', event.target.value)} /></Field><Field label="Doctor / referral"><Input data-testid="input-appointment-doctor" value={form.doctor} onChange={(event) => set('doctor', event.target.value)} placeholder="Optional" /></Field></div><div className="mt-4"><div className="mb-2 flex items-center justify-between"><span className="text-xs font-semibold text-muted-foreground">Available slots</span>{slotsQuery.isLoading && <span className="text-[10px] text-muted-foreground">Checking...</span>}</div><div className="grid grid-cols-2 gap-2 sm:grid-cols-3">{slots.map((slot) => { const available = slot.status !== 'blocked' && slot.booked < slot.capacity; return <button type="button" key={slot.id} disabled={!available} data-testid={`button-slot-${slot.id}`} onClick={() => { set('slotId', slot.id); set('time', slot.startTime); }} className={cx('rounded-xl border px-2 py-2 text-left transition', form.slotId === slot.id ? 'border-primary bg-[#edf8f5] text-primary' : 'border-border hover:border-primary/50', !available && 'cursor-not-allowed opacity-40')}><div className="mono text-xs font-bold">{slot.startTime}</div><div className="mt-0.5 text-[10px] text-muted-foreground">{slot.booked}/{slot.capacity} booked</div></button> })}</div>{!slotsQuery.isLoading && form.testId && !slots.length && <div className="rounded-xl bg-muted p-3 text-xs text-muted-foreground">No slots available for this test and date.</div>}</div><Field label="Notes" className="mt-4"><textarea data-testid="textarea-appointment-notes" value={form.notes} onChange={(event) => set('notes', event.target.value)} placeholder="Anything the lab team should know" className="min-h-[72px] w-full resize-y rounded-xl border border-input bg-background p-3 text-sm outline-none focus:border-primary focus:ring-2 focus:ring-primary/15" /></Field></Panel>
      <Panel className="h-fit p-5"><div className="mb-5 flex items-center gap-3"><div className="grid size-9 place-items-center rounded-xl bg-[#fce9e8] text-[#b34b48]"><ReceiptText size={17} /></div><div><h2 className="font-semibold">Payment</h2><p className="text-xs text-muted-foreground">Capture collection state</p></div></div><Field label="Payment status"><Select data-testid="select-appointment-payment" value={form.paymentStatus} onChange={(event) => set('paymentStatus', event.target.value)}><option value="pending">Payment pending</option><option value="paid">Paid in full</option><option value="partial">Partially paid</option></Select></Field><div className="mt-5 rounded-xl bg-muted p-4"><div className="flex justify-between text-xs text-muted-foreground"><span>Test fee</span><span>{selectedTest ? money(selectedTest.price) : '—'}</span></div><div className="mt-3 flex justify-between border-t border-border pt-3 text-sm font-bold"><span>Due today</span><span>{selectedTest ? money(selectedTest.price) : '—'}</span></div></div><Button type="submit" disabled={createMutation.isPending} className="mt-5 w-full" data-testid="button-submit-appointment"><CalendarDays size={16} />{createMutation.isPending ? 'Booking...' : 'Confirm appointment'}</Button><p className="mt-3 text-center text-[10px] leading-relaxed text-muted-foreground">A booking reference and patient update will be created automatically.</p></Panel></form>}</>;
}

function Tests() {
  const query = useListTests();
  const tests = query.data ?? [];
  return <><PageTitle eyebrow="Configuration / Catalogue" title="Test catalogue" detail="Active investigations available to the frontdesk and lab teams." action={<div className="flex items-center gap-2 rounded-xl bg-[#e5f5f1] px-3 py-2 text-xs font-semibold text-[#167366]"><span className="size-2 rounded-full bg-primary" /> {tests.length} active tests</div>} /><Panel><QueryState loading={query.isLoading} error={!!query.error} retry={() => query.refetch()}>{tests.length ? <div className="overflow-x-auto"><table className="w-full min-w-[720px] text-left"><thead className="bg-muted/45 text-[10px] uppercase tracking-[.12em] text-muted-foreground"><tr><th className="px-5 py-3 font-bold">Investigation</th><th className="px-4 py-3 font-bold">Department</th><th className="px-4 py-3 font-bold">Turnaround</th><th className="px-4 py-3 font-bold">Price</th><th className="px-5 py-3 font-bold">State</th></tr></thead><tbody className="divide-y divide-border">{tests.map((test) => <tr key={test.id} data-testid={`row-test-${test.id}`} className="hover:bg-muted/35"><td className="px-5 py-4"><div className="flex items-center gap-3"><div className="grid size-9 place-items-center rounded-xl bg-[#e8f0f8] text-[#32607e]"><FlaskConical size={16} /></div><div><div className="text-sm font-semibold">{test.name}</div><div className="mono mt-0.5 text-[10px] text-muted-foreground">{test.shortName}</div></div></div></td><td className="px-4 py-4 text-xs text-muted-foreground">{test.department}</td><td className="px-4 py-4 text-xs">{test.duration} min</td><td className="px-4 py-4 mono text-xs font-bold">{money(test.price)}</td><td className="px-5 py-4"><span className={cx('rounded-lg px-2 py-1 text-[10px] font-bold', test.active ? statusTone('available') : statusTone('blocked'))}>{test.active ? 'Active' : 'Inactive'}</span></td></tr>)}</tbody></table></div> : <EmptyState icon={FlaskConical} title="No active tests" detail="Your active diagnostic test catalogue will appear here." />}</QueryState></Panel></>;
}

function Reports() {
  const summaryQuery = useGetDashboardSummary();
  const pending = summaryQuery.data?.reportsPending;
  return <><PageTitle eyebrow="Clinical ops / Queue" title="Reports" detail="The report workspace is intentionally scoped to queue visibility for this release." /><Panel className="overflow-hidden"><div className="border-b border-border bg-[#edf8f5] px-6 py-5"><div className="flex items-start gap-3"><div className="grid size-10 place-items-center rounded-xl bg-primary text-primary-foreground"><FileText size={19} /></div><div><h2 className="font-semibold text-[#175b54]">Report queue visibility</h2><p className="mt-1 max-w-2xl text-sm text-[#4d766f]">Report generation, authoring, and publishing are outside the current operational scope. This view keeps the pending volume visible so frontdesk can set expectations.</p></div></div></div><div className="grid gap-5 p-6 md:grid-cols-[.8fr_1fr]"><div className="rounded-2xl border border-border bg-card p-5"><div className="text-xs font-semibold text-muted-foreground">Pending reports today</div><div className="mt-3 text-5xl font-bold tracking-[-.07em]">{summaryQuery.isLoading ? '—' : pending ?? 0}</div><p className="mt-2 text-xs text-muted-foreground">Updated from the operational summary.</p></div><div className="flex items-center rounded-2xl border border-dashed border-border bg-muted/40 p-5"><div><div className="font-semibold">No report records to display</div><p className="mt-1 text-sm text-muted-foreground">When report authoring is enabled, this area will become the handoff queue for lab staff.</p></div></div></div></Panel></>;
}

function Analytics() {
  const query = useGetDashboardSummary();
  const summary = query.data;
  const trend = summary?.appointmentTrend ?? [];
  const max = Math.max(...trend.map((item) => item.value), 1);
  return <><PageTitle eyebrow="Workspace intelligence" title="Operational analytics" detail="A lightweight read on flow, completion, and collection pressure." action={<div className="rounded-xl border border-border bg-card px-3 py-2 text-xs text-muted-foreground">Today · live summary</div>} /><QueryState loading={query.isLoading} error={!!query.error} retry={() => query.refetch()}><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><MetricCard label="Conversion to completed" value={summary?.todayAppointments ? `${Math.round((summary.completed / summary.todayAppointments) * 100)}%` : '—'} detail="Today's appointment flow" icon={CheckCircle2} tone="teal" /><MetricCard label="Collection coverage" value={summary?.revenue ? money(summary.revenue) : '—'} detail={`${summary?.pendingPayments ?? 0} still pending`} icon={CircleDollarSign} tone="amber" /><MetricCard label="Confirmed share" value={summary?.todayAppointments ? `${Math.round((summary.confirmed / summary.todayAppointments) * 100)}%` : '—'} detail="Before patient arrival" icon={CalendarDays} tone="blue" /><MetricCard label="Patient updates" value={summary?.whatsappSent ?? '—'} detail="WhatsApp messages sent" icon={Phone} tone="coral" /></div><div className="mt-5 grid gap-5 lg:grid-cols-[1.3fr_.7fr]"><Panel className="p-5"><h2 className="font-semibold">Seven-day throughput</h2><p className="mt-1 text-xs text-muted-foreground">Appointments booked by day</p><div className="mt-7 flex h-[250px] items-end gap-2 sm:gap-5">{trend.length ? trend.map((item) => <div key={item.label} className="flex h-full flex-1 flex-col items-center justify-end gap-2"><div className="flex w-full max-w-12 flex-1 items-end rounded-t-lg bg-muted"><div className="w-full rounded-t-lg bg-primary" style={{ height: `${Math.max(8, item.value / max * 100)}%` }} /></div><span className="mono text-[10px] text-muted-foreground">{item.label}</span><span className="text-xs font-bold">{item.value}</span></div>) : <div className="flex w-full items-center justify-center text-sm text-muted-foreground">No throughput data available</div>}</div></Panel><Panel className="p-5"><h2 className="font-semibold">Operational pulse</h2><p className="mt-1 text-xs text-muted-foreground">The numbers that need attention</p><div className="mt-6 space-y-5"><PulseRow label="Pending appointments" value={summary?.pending ?? 0} tone="amber" /><PulseRow label="Pending payments" value={summary?.pendingPayments ?? 0} tone="coral" /><PulseRow label="Reports pending" value={summary?.reportsPending ?? 0} tone="blue" /></div><div className="mt-7 border-t border-border pt-4 text-xs text-muted-foreground"><span className="font-semibold text-foreground">Reading this:</span> keep pending volume low before the final collection window.</div></Panel></div></QueryState></>;
}
function PulseRow({ label, value, tone }: { label: string; value: number; tone: 'amber' | 'coral' | 'blue' }) {
  return <div className="flex items-center justify-between"><div className="flex items-center gap-2 text-sm"><span className={cx('size-2 rounded-full', tone === 'amber' && 'bg-[#e8a84d]', tone === 'coral' && 'bg-[#d47770]', tone === 'blue' && 'bg-[#7397b2]')} />{label}</div><span className="mono text-sm font-bold">{value}</span></div>;
}

function SettingsPage() {
  return <><PageTitle eyebrow="Workspace admin" title="Settings" detail="A quiet summary of the operating context for this diagnostic center." /><div className="grid gap-5 lg:grid-cols-[.72fr_1.28fr]"><Panel className="p-6"><div className="flex items-center gap-3"><div className="grid size-11 place-items-center rounded-2xl bg-sidebar text-sidebar-foreground"><Stethoscope size={20} /></div><div><div className="font-bold">Nivara Diagnostics</div><div className="text-xs text-muted-foreground">Andheri West workspace</div></div></div><div className="mt-7 space-y-4"><SettingLine label="Workspace ID" value="NVR-MUM-042" mono /><SettingLine label="Timezone" value="Asia / Kolkata" /><SettingLine label="Currency" value="INR · ₹" /><SettingLine label="Operating hours" value="07:00 — 21:00" /></div></Panel><Panel><div className="border-b border-border px-6 py-5"><h2 className="font-semibold">Operational preferences</h2><p className="mt-1 text-xs text-muted-foreground">Reference settings for this workspace release.</p></div><div className="divide-y divide-border"><SettingToggle label="WhatsApp appointment updates" detail="Patient-facing messages are tracked in activity." enabled /><SettingToggle label="Payment reconciliation reminders" detail="Keep unpaid appointments visible in the daily queue." enabled /><SettingToggle label="Report publishing workflow" detail="Available in a future clinical operations release." enabled={false} /></div></Panel></div></>;
}
function SettingLine({ label, value, mono = false }: { label: string; value: string; mono?: boolean }) { return <div className="flex items-center justify-between gap-4 text-sm"><span className="text-muted-foreground">{label}</span><span className={cx('font-semibold', mono && 'mono text-xs')}>{value}</span></div>; }
function SettingToggle({ label, detail, enabled }: { label: string; detail: string; enabled: boolean }) { return <div className="flex items-center justify-between gap-5 px-6 py-5"><div><div className="text-sm font-semibold">{label}</div><div className="mt-1 text-xs text-muted-foreground">{detail}</div></div><div className={cx('relative h-6 w-11 shrink-0 rounded-full', enabled ? 'bg-primary' : 'bg-muted')}><span className={cx('absolute top-1 size-4 rounded-full bg-card transition-transform', enabled ? 'translate-x-6' : 'translate-x-1')} /></div></div>; }

function Router() {
  const [location] = useLocation();
  return <ErrorBoundary resetKey={location}><Shell><Switch><Route path="/" component={Dashboard} /><Route path="/appointments" component={Appointments} /><Route path="/patients" component={Patients} /><Route path="/new-appointment" component={NewAppointment} /><Route path="/tests" component={Tests} /><Route path="/reports" component={Reports} /><Route path="/analytics" component={Analytics} /><Route path="/settings" component={SettingsPage} /><Route component={NotFound} /></Switch></Shell></ErrorBoundary>;
}
function App() {
  return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><Router /></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>;
}
export default App;